// Example MCP server: tool schemas generated by @modelcontextprotocol/sdk from Zod (real generator output).
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { z } from "zod";

const server = new McpServer({ name: "zod-example", version: "1.0.0" });
const ok = async () => ({ content: [{ type: "text", text: "ok" }] });

server.registerTool(
  "create_issue",
  {
    description: "Create an issue.",
    inputSchema: {
      title: z.string().min(1).max(200),
      body: z.string().optional(),
      labels: z.array(z.string()).max(10).optional(),
      priority: z.enum(["low", "medium", "high"]).default("medium"),
      assignee: z.string().email().nullable().optional(),
      due: z.string().datetime().optional(),
    },
  },
  ok,
);

server.registerTool(
  "query",
  {
    description: "Run a filtered query.",
    inputSchema: {
      filter: z.discriminatedUnion("kind", [
        z.object({ kind: z.literal("text"), text: z.string() }),
        z.object({ kind: z.literal("range"), from: z.number().int(), to: z.number().int().positive() }),
      ]),
      page: z.number().int().nonnegative().optional(),
      meta: z.record(z.string(), z.unknown()).optional(),
    },
  },
  ok,
);

server.registerTool(
  "set_flags",
  {
    description: "Set feature flags.",
    inputSchema: {
      flags: z.array(z.object({ name: z.string().regex(/^[a-z_]+$/), value: z.union([z.boolean(), z.number(), z.string()]) })),
      reason: z.string().optional(),
    },
  },
  ok,
);

await server.connect(new StdioServerTransport());
